parameters.jsCode:
const response = $input.first().json;
const rows = Array.isArray(response.data) ? response.data : [];

const escapeHtml = (value) => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('\"', '&quot;')
  .replaceAll("'", '&#39;');

let tableHtml;
if (rows.length === 0) {
  tableHtml = '<p>The query returned no rows.</p>';
} else {
  const columns = Object.keys(rows[0]);
  const header = columns.map((column) => `<th style=\"padding:8px;border:1px solid #ccc;text-align:left\">${escapeHtml(column)}</th>`).join('');
  const body = rows.map((row) => {
    const cells = columns.map((column) => `<td style=\"padding:8px;border:1px solid #ccc\">${escapeHtml(row[column])}</td>`).join('');
    return `<tr>${cells}</tr>`;
  }).join('');
  tableHtml = `<table style=\"border-collapse:collapse;font-family:Arial,sans-serif;font-size:13px\"><thead><tr>${header}</tr></thead><tbody>${body}</tbody></table>`;
}

return [{
  json: {
    subject: `IBM i table extract - ${rows.length} row(s)`,
    htmlContent: `<h2>IBM i table extract</h2><p>Rows returned: <strong>${rows.length}</strong></p>${tableHtml}<p style=\"font-size:12px;color:#666\">Request ID: ${escapeHtml(response.request_id || '')}</p>`,
    textContent: `IBM i table extract\nRows returned: ${rows.length}\nRequest ID: ${response.request_id || ''}`,
    rowCount: rows.length
  }
}];
